From cube to vortex.

vec3 applyFractalWarp(vec3 p) {
    for (float i = 0.; i < 1.; i += 0.25) {
        float layerStrength = ((0.25 + 0.15 * sin(i * 8.6 + uChi * 0.3))
            * (0.8 + 0.4 * uDrive)) * uWarpStrength;
        float layerFreq = 0.9 + i * 0.5;
        vec3 seed = p * layerFreq + vec3(uChi * 0.25, uAlpha * 0.18, uDelta);
        p += smoothWarp(seed, layerStrength);
    }
    return p;
}

float map(vec3 p) {
    vec3 cube = vec3(2.0);
    float central = baseBox(applyFractalWarp(p), cube * 0.0);
    vec3 q = applyFractalWarp(abs(p) - vec3(1.0 + uDrive * 8.0));
    return min(central, baseBox(q, cube));
}

